public class Fine { public int Id{get;set;} public int StudentId{get;set;} public string Reason{get;set;}=""; public decimal Amount{get;set;} public bool IsPaid{get;set;} public Student? Student{get;set;} }
public class FundTransaction { public int Id{get;set;} public string TransactionType{get;set;}="Income"; public string Description{get;set;}=""; public decimal Amount{get;set;} public DateTime TransactionDate{get;set;}=DateTime.Today; }
public class Disbursement { public int Id{get;set;} public string Payee{get;set;}=""; public string Purpose{get;set;}=""; public decimal Amount{get;set;} public DateTime DisbursementDate{get;set;}=DateTime.Today; public string Status{get;set;}="Pending"; }
public class ActivityLog { public int Id{get;set;} public int UserId{get;set;} public string Action{get;set;}=""; public DateTime CreatedAt{get;set;}=DateTime.UtcNow; public User? User{get;set;} }
